//! `emit_vb` — prints the HLSL Visibility-Buffer analytic barycentric/attribute-interpolation
//! function spans generated by tracing `boyko_shaderdsl::vb`'s generic bodies over the `Emit`
//! backend (`feature = "emit"`), mirroring `emit_field`'s pass-1 "print to stdout, splice by
//! hand" idiom.
//!
//! Pass 1: this PRINTS to stdout. It does NOT splice into
//! `crates/boyko_rhi_vulkan/shaders/vb_geom_fetch.hlsli` and does NOT recompile any `.spv` —
//! that splice is done once, by hand, at rung R8 (`vb_geom_fetch.hlsli`'s own doc pins the
//! sentinels this bin's output must match verbatim).
//!
//! Run: `cargo run -p boyko_shaderdsl --features emit --bin emit_vb`

fn main() {
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_vb_barycentric());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_vb_interp());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_vb_uv_grad());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_vb_near_clip());
}
